"""WARM G1 memory module for LongMemEval-V2, single file, live at query time.

memory.query(question, image) runs the frozen G1 design (FREEZE6, 2026-11-17) end to end: Gemini controller over a compiled
index of the inserted trajectories, VERIFY + CRUX + OPTCHECK, final rule c1, a second controller pass for undecided choice
questions, the form-control-table renderer (WARM engine experience_form_tables), and verify-and-reread: a Qwen3.5-9B draft
answer, ANSWER-CHECK against verbatim state text, and the Evidence Check block first when the draft is contradicted.

The stage code is the merged adapter (writerslogic/warm benchmarks/lme2 at d096063f) embedded verbatim below; each embedded
source is checked against its sha256 at import. The live orchestration after the embedded sources reproduces the staged
pipeline's call sequence (span_stage, check_stages, rules, ctl_pass2, run_lme2 prompts) for one question.
Inputs at query time: the question text and image, and the inserted trajectories. No question ids, labels or caches."""
_EMBEDDED = {}
_EMBEDDED['fileio'] = ('429b06043f22a7f0eebfe274b59e8bce61b25c3e059bf66dfa0e085df60e4f67', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""File helpers that close what they open: the stage scripts read JSON, JSON lines and pickles and\nappend one JSON line per finished question."""\nimport json, pickle\n\n\ndef read_json(p):\n    with open(p) as f:\n        return json.load(f)\n\n\ndef write_json(obj, p):\n    with open(p, "w") as f:\n        json.dump(obj, f)\n\n\ndef read_pickle(p):\n    with open(p, "rb") as f:\n        return pickle.load(f)\n\n\ndef lines(p):\n    """The lines of a text file, read lazily; the file closes when the iteration ends."""\n    with open(p) as f:\n        yield from f\n\n\ndef append_line(p, text):\n    with open(p, "a") as f:\n        f.write(text)\n')
_EMBEDDED['prompts'] = ('8c610b9233d5627a195ce644bdb05375022f2d70bc7c4f67ac4e1f5312d36633', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Frozen G1 prompt strings, tool schemas and constants, extracted from the reference files; check_frozen.py asserts equality."""\nimport re\n\ndef _schema(s):\n    if isinstance(s, dict):\n        return {("type" if k == "type" else k): (v.upper() if k == "type" and isinstance(v, str) else _schema(v)) for k, v in s.items() if k not in ("additionalProperties",)}\n    if isinstance(s, list): return [_schema(x) for x in s]\n    return s\nPRICES = {"gemini-3.8-flash": (0.75e-6, 3.75e-6), "gemini-3.6-flash": (0.75e-6, 3.75e-6), "gemini-3-flash-preview": (0.5e-6, 3.0e-6), "gemini-3.5-flash": (0.5e-6, 3.0e-6),\n          "gemini-3.5-flash-lite": (0.3e-6, 2.5e-6), "gemini-3.1-flash-lite": (0.25e-6, 1.5e-6), "gemini-3.7-flash": (0.75e-6, 3.75e-6)}\n\nWORKFLOW = """You are the memory module of an assistant that answers questions about a customized web application. The application was recorded in many sessions (trajectories) of agents using it; each trajectory is a list of states (page snapshot + the action taken at that state). You are NOT the answering model: you choose which raw states the answering model will read. It reads only the states you select (page text and screenshots) plus your analysis, with no tools, so the answer must be visible in them.\n\nYour tools: a compiled index of the memory (regions: deduplicated page fragments; transitions: what each action did to a page; episodes: one line per step of each trajectory with the state index; pages: full element inventories; notes: session summaries; value_history) and raw-state tools (find_states: search every state; show_state: preview a state; trajectory_goal). Finish with exactly one submit_spans call.\n\nWorkflow:\n1. Plan in two lines: what the answer needs (which page, element, option, value, ordering, count, or steps) and which kind of evidence shows it.\n2. Round 1: issue 3 to 5 independent calls in parallel with different kinds and wordings (pages / regions / episodes / find_states) using the concrete labels in the question.\n3. Locate states: episodes list "state_index. action" per trajectory, so an episode tells you which state index shows the page after each step; find_states returns state indices directly. Use show_state to confirm a state really contains the item before selecting it.\n4. Choose spans: the smallest ranges that show the evidence. For a procedure (\'how do I...\'), select the contiguous states of the best successful trajectory, from the start page to the state that completes it (the reader counts steps from them), and add the states of a failed or ineffective attempt only if the question is about problems. For a value or option question, select the state where the element is visible (and the state before/after if the question is about a change). For a question that may assume something that does not exist, select the state(s) of the relevant page that is fully shown but lacks the element, and say so in the analysis. Prefer distinct trajectories over near-duplicates. Put the most important span first. Total at most 20 states; count inclusively.\n5. Stop searching when every item the question asks about is covered by a selected state; do not keep confirming. You work in at most {N} rounds, with several tool calls per round; a progress note tells you the rounds left; when two remain, call submit_spans.\n6. Give an honest support verdict in submit_spans: supported / partial / absent. Use absent when you searched the relevant pages and they do not contain what the question asks for (a feature, option, setting, column, value or step that is not there, or a question whose premise the pages contradict); the downstream model will then tell the user it does not exist instead of guessing. Use supported only when a selected state visibly shows the asked fact. Do not choose absent merely because the search was hard: if the item may exist on a page you have not opened, keep searching or say partial.\n7. Do not answer from general knowledge; every claim in the analysis must be visible in a selected state. Plain text, no LaTeX."""\n\nTOOL_SPECS = [\n {"type": "function", "function": {"name": "search", "description": "Lexical search over one kind of compiled memory item. kind: regions (deduplicated page fragments), transitions (what an action did to a page), episodes (recorded task attempts with action paths), pages (page templates with element inventories), notes (summaries of what recorded sessions did). Returns item ids with a snippet.",\n   "parameters": {"type": "object", "properties": {"kind": {"type": "string", "enum": ["regions", "transitions", "episodes", "pages", "notes"]}, "query": {"type": "string"}, "k": {"type": "integer"}}, "required": ["kind", "query"]}}},\n {"type": "function", "function": {"name": "open", "description": "Full text of an item by id (R.. region, T.. transition, E:<traj> episode, P.. page inventory listing every element observed on that page with observation counts, N:<traj> notes).",\n   "parameters": {"type": "object", "properties": {"id": {"type": "string"}}, "required": ["id"]}}},\n {"type": "function", "function": {"name": "transitions_from", "description": "All recorded actions taken on a page template (P.. id) with their observed effects.",\n   "parameters": {"type": "object", "properties": {"page_id": {"type": "string"}}, "required": ["page_id"]}}},\n {"type": "function", "function": {"name": "value_history", "description": "How the value/state of page elements matching the query changed across steps of each recorded session.",\n   "parameters": {"type": "object", "properties": {"query": {"type": "string"}}, "required": ["query"]}}},\n {"type": "function", "function": {"name": "submit_brief", "description": "Finish: hand the downstream reader a support brief.",\n   "parameters": {"type": "object", "properties": {\n     "answer": {"type": "string", "description": "Best answer to the question, in exactly the form the question asks for (short phrases, a letter, a number, or a statement). Empty only if nothing in memory bears on it."},\n     "evidence": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "quote": {"type": "string"}}, "required": ["id", "quote"]}, "description": "Exact quotes from memory items supporting the answer, with their item ids."},\n     "premise": {"type": "string", "enum": ["ok", "false", "unsure"], "description": "false only if memory positively shows something the question presupposes does not exist or does not hold (for instance a complete page inventory lacking the element); unsure if memory does not settle it."},\n     "correction": {"type": "string", "description": "If premise is false: what the question assumes, and what is true instead. Otherwise empty."}},\n    "required": ["answer", "evidence", "premise"]}}},\n]\n\nMAX_SPAN_STATES = 20\ndef _p(d, req): return {"type": "object", "properties": d, "required": req}\nS = lambda t: {"type": t}\nEXTRA_SPECS = [\n {"type": "function", "function": {"name": "find_states", "description": "Lexical search over every recorded STATE (raw page snapshots) of all trajectories. Returns trajectory id, state index, url, action. Use it to locate where text, labels or values appear.", "parameters": _p({"query": S("string"), "k": S("integer")}, ["query"])}},\n {"type": "function", "function": {"name": "show_state", "description": "Preview one raw state (url, action, first 2500 chars of its page text) to check it contains what you need before selecting it.", "parameters": _p({"trajectory_id": S("string"), "state_index": S("integer"), "max_chars": S("integer")}, ["trajectory_id", "state_index"])}},\n {"type": "function", "function": {"name": "trajectory_goal", "description": "Goal, outcome and state count of one trajectory.", "parameters": _p({"trajectory_id": S("string")}, ["trajectory_id"])}},\n]\nSUBMIT_SPANS = {"type": "function", "function": {"name": "submit_spans", "description": "Finish. Select raw trajectory spans for the downstream reader (it sees those states, their page text and screenshots, and your analysis, but cannot call tools).",\n  "parameters": _p({\n    "analysis": {"type": "string", "description": "Short support analysis: the answer you believe the evidence supports (in the form the question asks), which span shows what, and any step that failed or had no effect. If the question presupposes something the states show is absent, say what is true instead."},\n    "support": {"type": "string", "enum": ["supported", "partial", "absent"], "description": "Does the evidence in the states you selected establish what the question asks? supported: the asked fact is visible in the selected states. partial: only some of the asked items are visible. absent: after searching, the application/pages do not contain the asked feature, option, setting, value or step (including when the question assumes something the pages do not have), so no selected state can show it."},\n    "spans": {"type": "array", "description": "Most important first. Zero-based inclusive state ranges; total states across spans at most 20.", "items": _p({"trajectory_id": S("string"), "start_state_index": S("integer"), "end_state_index": S("integer")}, ["trajectory_id", "start_state_index", "end_state_index"])}},\n    ["analysis", "support", "spans"])}}\n\nVERIFY_SYSTEM = """You verify one memory-retrieval step for a question about a customized web application. A retrieval module selected states (page snapshots with the action taken at each) from recorded sessions and wrote a draft analysis. You see the question, the draft analysis, and the full text of the selected states. Work only from the state text; never use general knowledge about what such an application usually contains. If the draft analysis conflicts with the state text, the state text wins.\nDo this:\n1. Presuppositions: list every page, control, option, value, ordering, count or relationship the question presupposes or asks about. For each, give an exact short quote from a state text that establishes it, or "none", and a status: shown (quote establishes it), not_shown (not in the selected states), or contradicted (the states show something incompatible, or show the relevant page fully and the presupposed item is not on it).\n2. Facts: for the asked item read the exact label, value, selected option and position from the state text. For a default or initial value use the earliest selected state where the control appears, before later actions changed it, unless the question is about a change.\n3. premise: holds when every presupposition is shown; violated when at least one is contradicted; unclear when the needed page is not among the states.\n4. support: supported when the asked fact is visible in the states, partial when only part is, absent when the application pages shown do not contain what the question asks for.\n5. analysis: two to five sentences in plain text giving the answer in the form the question asks and which state shows it (trajectory id, state index), with exact values. If premise is violated, say that the asked item does not exist or is not available and state what is there instead.\nCall verify exactly once."""\nVERIFY_DECL = [{"name": "verify", "description": "Report the verification.", "parameters": _schema({"type": "object", "properties": {\n    "presuppositions": {"type": "array", "items": {"type": "object", "properties": {"claim": {"type": "string"}, "quote": {"type": "string"}, "status": {"type": "string", "enum": ["shown", "not_shown", "contradicted"]}}, "required": ["claim", "quote", "status"]}},\n    "premise": {"type": "string", "enum": ["holds", "violated", "unclear"]}, "support": {"type": "string", "enum": ["supported", "partial", "absent"]}, "analysis": {"type": "string"}},\n    "required": ["presuppositions", "premise", "support", "analysis"]})}]\n\nCRUX_SYSTEM = """You check one question about a customized web application for a false premise, using only the text of states (page snapshots with the action taken at each) selected from recorded sessions. Never use general knowledge about what such an application usually contains.\nSome questions are traps: they ask to name, count or give the value of something whose existence they assume (an extra stage, a second button, an option, a field, a change, a shared element, a step) but which the application does not have. Do this:\n1. target: the specific thing the question asks you to name, count, compare or give a value for, including every condition the question attaches to it (position, page, which forms share it, what triggers it).\n2. evidence: one to four exact, verbatim substrings of the state text that show that target exists with those conditions (copy characters exactly, no paraphrase). Each gives trajectory id and state index. Do not quote text that only shows the surrounding page.\n3. verdict: exists when the evidence shows the target with all its conditions; missing when the relevant page or result is shown and the target or one of its conditions is not there or is contradicted; unclear when the states do not show the relevant page or result. A plain question with no presupposed item (a yes/no or true/false check, a procedure that the states show, a value that the states show) is exists.\n4. note: one or two sentences: what is there instead when missing.\nCall cite exactly once."""\nCRUX_DECL = [{"name": "cite", "description": "Report the premise check.", "parameters": _schema({"type": "object", "properties": {\n    "target": {"type": "string"}, "quotes": {"type": "array", "items": {"type": "object", "properties": {"trajectory_id": {"type": "string"}, "state_index": {"type": "integer"}, "text": {"type": "string"}}, "required": ["trajectory_id", "state_index", "text"]}},\n    "verdict": {"type": "string", "enum": ["exists", "missing", "unclear"]}, "note": {"type": "string"}}, "required": ["target", "quotes", "verdict", "note"]})}]\n\nOPTCHECK_SYSTEM = """You check the answer options of one question about a customized web application against the text of states (page snapshots with the action taken at each) selected from recorded sessions. Work only from the state text; never use general knowledge about what such an application usually contains.\n1. options: list every answer option the question offers (for a true/false or yes/no question the options are the two values; for a question with listed choices, each choice; for a question that asks for listed items, each candidate item the question names).\n2. For each option give verdict supported (the state text shows it is the right answer), refuted (the state text shows it is wrong), or not_shown, and one to three exact, verbatim substrings of the state text with trajectory id and state index that decide it. Copy characters exactly; no paraphrase.\n3. Judge true/false statements in full: every part of the statement must hold for true; one counterexample in the states makes it false.\nCall cite exactly once."""\nOPTCHECK_DECL = [{"name": "cite", "description": "Report the option check.", "parameters": _schema({"type": "object", "properties": {\n    "options": {"type": "array", "items": {"type": "object", "properties": {"option": {"type": "string"}, "verdict": {"type": "string", "enum": ["supported", "refuted", "not_shown"]},\n      "quotes": {"type": "array", "items": {"type": "object", "properties": {"trajectory_id": {"type": "string"}, "state_index": {"type": "integer"}, "text": {"type": "string"}}, "required": ["trajectory_id", "state_index", "text"]}}}, "required": ["option", "verdict", "quotes"]}}}, "required": ["options"]})}]\n\nANSCHECK_SYSTEM = """You check a draft answer to one question about a customized web application against the text of states (page snapshots with the action taken at each) selected from recorded sessions. Work only from the state text; never use general knowledge.\nverdict: contradicted when some state text shows the draft answer is wrong (a different value, label, option, order, count or step is shown for exactly what the question asks); consistent when the state text supports it; unverifiable otherwise. Do not mark contradicted for wording differences or for details the question does not ask about.\nquotes: when contradicted, one to four exact, verbatim substrings of the state text (with trajectory id and state index) that show the correct fact. Copy characters exactly; no paraphrase.\nCall cite exactly once."""\nANSCHECK_DECL = [{"name": "cite", "description": "Report the answer check.", "parameters": _schema({"type": "object", "properties": {\n    "verdict": {"type": "string", "enum": ["consistent", "contradicted", "unverifiable"]}, "quotes": {"type": "array", "items": {"type": "object", "properties": {"trajectory_id": {"type": "string"}, "state_index": {"type": "integer"}, "text": {"type": "string"}}, "required": ["trajectory_id", "state_index", "text"]}}}, "required": ["verdict", "quotes"]})}]\n\nCHOICE_PATTERN = re.compile(r"true or false|yes or no|which of the following|\\([a-d]\\)|^\\s*[a-d][\\).]\\s|options?\\s*:|choices?\\s*:|choose (one|from|among)",re.I|re.M)\n\nSUPPORT_VERDICT = {"supported": "SUPPORTED: the selected states show the asked fact.", "partial": "PARTIAL: the selected states show only part of what is asked.", "absent": "ABSENT: a search of the memory found no page or state that contains what the question asks for. If the question assumes a feature, option, setting, value or step that is not there, say that it does not exist or is not available in this application, and state what is there instead. Do not guess."}\n\nCONTROLLER_MODEL = "gemini-3.6-flash"\nCONTROLLER_MAX_STEPS = 14\nCONTROLLER_EXTRA = {"thinkingLevel": "MEDIUM"}\nPER, TOT = 24000, 140000\nFORM_TOKEN_BUDGET = 140000\nTOKENS_PER_CHAR = 0.42\n\n\ndef workflow(max_steps):\n    return WORKFLOW.replace("{N}", str(max_steps))\n\n\ndef stage_body(SYSTEM, msg, DECL, name):\n    return {"systemInstruction": {"parts": [{"text": SYSTEM}]}, "contents": [{"role": "user", "parts": [{"text": msg}]}], "tools": [{"functionDeclarations": DECL}],\n            "toolConfig": {"functionCallingConfig": {"mode": "ANY", "allowedFunctionNames": [name]}}, "generationConfig": {"maxOutputTokens": 8000, "thinkingConfig": {"thinkingLevel": "MEDIUM", "includeThoughts": False}}}\n\n\ndef verify_message(q, r, states):\n    return f"QUESTION:\\n{q}\\n\\nDRAFT ANALYSIS (retrieval module, support verdict {r[\'support\']}):\\n{r[\'analysis\']}\\n\\nSELECTED STATES:\\n{states}"\n\n\ndef states_message(q, states):\n    return f"QUESTION:\\n{q}\\n\\nSELECTED STATES:\\n{states}"\n\n\ndef anscheck_message(q, answer, states):\n    return f"QUESTION:\\n{q}\\n\\nDRAFT ANSWER:\\n{answer}\\n\\nSELECTED STATES:\\n{states}"\n\n\nPASS2_NO_OPTIONS = "the asked items"\n\n\ndef pass2_question(question, opts):\n    return question + f"\\n\\n[Memory note: a first search selected states that did not decide between these options: {opts}. Find and select the states that directly show the facts each option depends on.]"\n\n\ndef evidence_check(grounded):\n    return \'## Evidence Check\\nThese verbatim lines from the selected states bear directly on the question; check your answer against them first:\\n\' + \'\\n\'.join(f\'- {q["trajectory_id"]} state {q["state_index"]}: "{q["text"]}"\' for q in grounded)\n\n\nFORM_HEADER = "- Form controls (structured from the page text; * = selected option):\\n"\n\n\ndef form_block(new, n_rows):\n    return FORM_HEADER + "\\n".join("  " + r for r in new) + (f"\\n  [{n_rows - len(new)} controls unchanged from an earlier state omitted]" if len(new) < n_rows else "") + "\\n"\n\n\nBUDGET_CUT = "\\n  [... page text cut at the context budget]"\n')
_EMBEDDED['envmodel'] = ('f9b9ad8a69fbfb22f9c08a62cdffe6ab9575da1f87fd1c875c2bb8c38c36fb9d', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Write-time environment model for LongMemEval-V2 trajectories (deterministic, no LLM, no gold).\nParts: hash-consed AXTree region units (C1), transition effect table / automaton (C2), episodes (C3), value variants (C4)."""\nimport re, math, collections, ast, hashlib\nfrom urllib.parse import unquote\n\nLINE = re.compile(r"^(\\t*)(?:\\[(\\d+)\\]\\s+)?(\\S+)(?: \'((?:[^\'\\\\]|\\\\.)*)\')?(.*)$")\nKEEP = re.compile(r"(value=\'(?:[^\'\\\\]|\\\\.)*\'|\\bchecked(?:=\\w+)?\\b|\\bdisabled\\b|\\brequired\\b|\\bselected\\b|\\bexpanded=\\w+|\\bpressed=\\w+|\\blevel=\\d+)")\nSKIP_ROLES = {\'generic\', \'list\', \'listitem\', \'none\', \'LabelText\', \'group\', \'presentation\', \'separator\', \'paragraph\', \'Section\', \'DescriptionList\', \'rowgroup\', \'cell_group\'}\nUNIT_MAX = 1500\n\ndef label(role, name):\n    return f"{role} \'{name[:80]}\'" if name else role\n\nclass Node:\n    __slots__ = (\'role\', \'name\', \'pk\', \'ch\', \'h\', \'c\', \'size\', \'bid\')\n    def __init__(s, role, name, pk, bid):\n        s.role, s.name, s.pk, s.ch, s.bid = role, name, pk, [], bid\n\ndef parse_tree(txt):\n    root = None; stack = []; bids = {}\n    for ln in txt.split(\'\\n\'):\n        if not ln.strip():\n            continue\n        m = LINE.match(ln)\n        if not m:\n            continue\n        d = len(m.group(1)); role = m.group(3); name = (m.group(4) or \'\').replace("\\\\\'", "\'")\n        pk = \' \'.join(KEEP.findall(m.group(5) or \'\'))\n        n = Node(role, name, pk, m.group(2))\n        if m.group(2):\n            bids[m.group(2)] = (role, name)\n        while len(stack) > d:\n            stack.pop()\n        if stack:\n            stack[-1].ch.append(n)\n        elif root is None:\n            root = n\n        else:\n            root.ch.append(n)\n        stack.append(n)\n    return root, bids\n\ndef finish(n):\n    """post-order: structural hash h, content hash c, size"""\n    for c in n.ch:\n        finish(c)\n    n.h = hash((n.role, n.name, tuple(c.h for c in n.ch)))\n    n.c = hash((n.role, n.name, n.pk, tuple(c.c for c in n.ch)))\n    own = len(n.name) + len(n.role) + 4 if (n.name or n.role not in SKIP_ROLES) else 0\n    n.size = own + sum(c.size for c in n.ch)\n\ndef render(n, depth=0, out=None, parent_name=None):\n    out = [] if out is None else out\n    show = False\n    if n.role == \'StaticText\':\n        if n.name.strip() and n.name != parent_name:\n            out.append(\' \' * depth + \'"\' + n.name[:200] + \'"\')\n        return out\n    if n.name or n.role not in SKIP_ROLES:\n        out.append(\' \' * depth + label(n.role, n.name)); show = True\n    for c in n.ch:\n        render(c, depth + (1 if show else 0), out, n.name)\n    return out\n\ndef value_lines(n, out=None):\n    out = [] if out is None else out\n    if n.pk:\n        out.append(label(n.role, n.name) + \' \' + n.pk)\n    for c in n.ch:\n        value_lines(c, out)\n    return out\n\ndef flat_lines(n, out):\n    if n.role == \'StaticText\':\n        if n.name.strip(): out.add(\'"\' + n.name[:160] + \'"\')\n    else:\n        if n.name: out.add(label(n.role, n.name))\n    for c in n.ch:\n        flat_lines(c, out)\n\ndef url_template(u):\n    u = unquote(u or \'\')\n    u = re.sub(r\'^https?://[^/]+\', \'\', u)\n    u = re.sub(r\'=[^&?]*\', \'=\', u)\n    u = re.sub(r\'[0-9a-f]{6,}\', \'<h>\', u)\n    u = re.sub(r\'\\d+\', \'#\', u)\n    return u[:140]\n\ndef title_template(t):\n    t = re.sub(r\'[0-9a-f]{8,}\', \'<h>\', t or \'\'); t = re.sub(r\'\\d+\', \'#\', t)\n    return t[:90]\n\ndef parse_action(a):\n    m = re.match(r"(\\w+)\\((.*)\\)\\s*$", a or \'\', re.S)\n    if not m: return (a or \'\', ())\n    try:\n        v = ast.literal_eval(\'(\' + m.group(2) + \',)\')\n    except Exception:\n        v = (m.group(2),)\n    return m.group(1), v\n\nERRW = re.compile(r"\\b(error|invalid|not allowed|denied|failed|failure|cannot|unable|forbidden|exception|required field|not found|no results)\\b", re.I)\n\ndef action_label(a, bids):\n    f, args = parse_action(a)\n    if f in (\'click\', \'hover\', \'fill\', \'select_option\', \'dblclick\', \'press\', \'focus\', \'check\', \'uncheck\', \'clear\', \'upload_file\', \'drag_and_drop\') and args:\n        r = bids.get(str(args[0]))\n        tgt = label(*r) if r else f"bid {args[0]}"\n        extra = \'\'\n        if f in (\'fill\', \'select_option\') and len(args) > 1:\n            extra = f" <- \'{str(args[1])[:60]}\'"\n        return f"{f} {tgt}{extra}"\n    if f == \'scroll\': return \'scroll\'\n    if f in (\'keyboard_press\',) and args: return f"press key {args[0]}"\n    if f == \'goto\' and args: return f"goto {url_template(str(args[0]))}"\n    return f"{f}{str(args)[:60]}" if f else \'noop\'\n\nclass Model:\n    def __init__(s):\n        s.units = {}          # h -> dict(text, bc, traj:set, nstates:int, vals:Counter, first)\n        s.eff = {}            # (tmpl, label) -> dict\n        s.eps = {}            # traj id -> text\n        s.tmpl = collections.defaultdict(lambda: dict(n=0, traj=set(), titles=collections.Counter(), out=collections.Counter(), inv=collections.Counter()))\n        s.raw_bytes = 0; s.unit_bytes_struct = 0; s.unit_occ = 0; s.unit_bytes_occ = 0; s.nstates = 0\n        s.aut = collections.Counter()\n\n    def add_traj(s, t):\n        prev_lines = None; prev_bids = None; prev_tmpl = None; steps = []\n        for st in t[\'states\']:\n            tree = st[\'accessibility_tree\'] or \'\'\n            s.raw_bytes += len(tree); s.nstates += 1\n            root, bids = parse_tree(tree)\n            if root is None:\n                continue\n            finish(root)\n            title = root.name\n            tm = (url_template(st[\'url\']), title_template(title))\n            td = s.tmpl[tm]; td[\'n\'] += 1; td[\'traj\'].add(t[\'id\']); td[\'titles\'][title[:80]] += 1\n            lines = set(); flat_lines(root, lines)\n            td[\'inv\'].update(lines)\n            s._units(root, [label(root.role, title)], t[\'id\'], st[\'state_index\'], tm)\n            if prev_lines is not None and st[\'action\'] is not None:\n                lab = action_label(st[\'action\'], prev_bids)\n                add = sorted(lines - prev_lines); rem = sorted(prev_lines - lines)\n                key = (prev_tmpl, lab)\n                e = s.eff.setdefault(key, dict(n=0, add=collections.Counter(), rem=collections.Counter(), nxt=collections.Counter(), traj=set(), loop=0, err=collections.Counter()))\n                e[\'n\'] += 1; e[\'traj\'].add(t[\'id\']); e[\'nxt\'][tm] += 1\n                for l in add[:60]: e[\'add\'][l] += 1\n                for l in rem[:60]: e[\'rem\'][l] += 1\n                for l in add:\n                    if ERRW.search(l): e[\'err\'][l[:120]] += 1\n                nochange = not add and not rem\n                if nochange: e[\'loop\'] += 1\n                td_prev = s.tmpl[prev_tmpl]; td_prev[\'out\'][lab] += 1\n                steps.append((st[\'state_index\'], lab, tm, nochange, [l for l in add if ERRW.search(l)][:2]))\n            prev_lines, prev_bids, prev_tmpl = lines, bids, tm\n        head = f"Trajectory {t[\'id\']} [{t[\'outcome\']}] goal: {t[\'goal\'][:300]}"\n        body = []\n        for i, lab, tm, nc, er in steps:\n            x = f"{i}. {lab}" + (\' (no visible change)\' if nc else \'\') + (f" (ERROR text: {\'; \'.join(er)})" if er else \'\')\n            body.append(x)\n        last = prev_tmpl[1] if prev_tmpl else \'\'\n        s.eps[t[\'id\']] = head + \'\\n\' + \'\\n\'.join(body) + f"\\nended on: {last}"\n\n    def _units(s, root, path, tid, sidx, tm):\n        def flush(batch, path):\n            if not batch: return\n            h = hash(tuple(n.h for n in batch)); c = hash(tuple(n.c for n in batch))\n            u = s.units.get(h)\n            sz = sum(n.size for n in batch)\n            s.unit_occ += 1; s.unit_bytes_occ += sz\n            if u is None:\n                lines = []\n                for n in batch: render(n, 0, lines)\n                text = \'\\n\'.join(lines)\n                if len(text.strip()) < 3: s.units[h] = None; return\n                u = dict(text=text, bc=\' > \'.join(path[-3:])[:200], tm=tm, traj=set(), n=0, vals=collections.Counter(), cs=set())\n                s.units[h] = u; s.unit_bytes_struct += len(text)\n            if u is None: return\n            u[\'n\'] += 1; u[\'traj\'].add(tid)\n            if c not in u[\'cs\'] and len(u[\'cs\']) < 12:\n                u[\'cs\'].add(c)\n                for n in batch:\n                    for v in value_lines(n): u[\'vals\'][v[:160]] += 1\n        def group(nodes, path):\n            batch = []; bs = 0\n            for n in nodes:\n                if n.size > UNIT_MAX and n.ch:\n                    flush(batch, path); batch = []; bs = 0\n                    group(n.ch, path + [label(n.role, n.name)])\n                else:\n                    if bs + n.size > UNIT_MAX:\n                        flush(batch, path); batch = []; bs = 0\n                    batch.append(n); bs += n.size\n            flush(batch, path)\n        group(root.ch, path)\n\n# ---------------- retrieval ----------------\nGENERIC_STOP = set(\'a an the of to in on at by for from with and or but is are was were be been it its this that these those as if then than so such into over after before when while what which who whom how do does did i me my our we you your he she they them their there here not no any some each one can could would should will may might also about between within during\'.split())\nBENCH_STOP = set("a an the of to in on is are was were be been it its this that these those and or for with as at by from what which who how do does did i my our we you your can could would should there their them then than into over after before when while if not no any some each one two three first second third last next many much more most also than about between within during page pages click clicks button buttons using use used action actions need want like would please answer final mark boxed short phrase phrases separated semicolon wrapped english e g".split())\nGENERIC = True\ndef stem(w):\n    for suf in (\'ing\', \'edly\', \'ed\', \'es\', \'s\'):\n        if len(w) > len(suf) + 3 and w.endswith(suf): return w[:-len(suf)]\n    return w\ndef toks(txt):\n    st = GENERIC_STOP if GENERIC else BENCH_STOP\n    return [stem(w) for w in re.findall(r"[a-z0-9]+", txt.lower()) if w not in st and len(w) > 1]\n\nBOILER = [r"Mark your final answer.*", r"Your final answer should.*", r"Action Space:.*", r"I am (?:working|using) (?:with|in|on)? ?our [^.]*?(?:portal|website|dashboard|forum|site)[^.]*\\.", r"Given the following action space.*"]\ndef clean_q(q):\n    if GENERIC: return q\n    q = q.split(\'Action Space:\')[0]\n    for b in BOILER[:2]: q = re.sub(b, \'\', q, flags=re.S)\n    return q\n\nclass BM25:\n    def __init__(s, docs, k1=1.2, b=0.75):\n        s.N = len(docs); s.inv = collections.defaultdict(list); s.dl = []\n        for i, d in enumerate(docs):\n            c = collections.Counter(d); s.dl.append(len(d))\n            for w, f in c.items(): s.inv[w].append((i, f))\n        s.avg = sum(s.dl) / max(1, s.N); s.k1, s.b = k1, b\n        s.idf = {w: math.log(1 + (s.N - len(p) + .5) / (len(p) + .5)) for w, p in s.inv.items()}\n    def search(s, qt, n=50):\n        sc = collections.defaultdict(float)\n        for w in sorted(set(qt)):\n            for i, f in s.inv.get(w, ()):\n                sc[i] += s.idf[w] * f * (s.k1 + 1) / (f + s.k1 * (1 - s.b + s.b * s.dl[i] / s.avg))\n        return sorted(sc.items(), key=lambda x: (-x[1], x[0]))[:n]\n\nclass Index:\n    def __init__(s, m):\n        s.m = m\n        s.uk = [h for h, u in m.units.items() if u]\n        s.ud = [m.units[h] for h in s.uk]\n        s.u_bm = BM25([toks(u[\'text\'] + \' \' + u[\'bc\'] + \' \' + u[\'tm\'][1]) for u in s.ud])\n        s.ek = list(m.eff)\n        s.ed = [s.eff_text(k) for k in s.ek]\n        s.e_bm = BM25([toks(t) for t in s.ed])\n        s.tk = [k for k, v in m.tmpl.items() if v[\'n\'] >= 1]\n        s.t_bm = BM25([toks(k[1] + \' \' + k[0] + \' \' + \' \'.join(m.tmpl[k][\'inv\'])) for k in s.tk])\n        s.pk = list(m.eps)\n        s.p_bm = BM25([toks(m.eps[k]) for k in s.pk])\n    def eff_text(s, k):\n        e = s.m.eff[k]; tm, lab = k\n        add = [l for l, _ in e[\'add\'].most_common(14)]; rem = [l for l, _ in e[\'rem\'].most_common(6)]\n        nxt = e[\'nxt\'].most_common(1)[0][0][1] if e[\'nxt\'] else \'\'\n        x = f"On page \'{tm[1]}\': {lab} (x{e[\'n\']}) -> "\n        if e[\'loop\'] == e[\'n\']: x += \'no visible change (self-loop)\'\n        else:\n            x += \'now shown: \' + \'; \'.join(add)\n            if rem: x += \' | gone: \' + \'; \'.join(rem)\n            x += f" | next page: \'{nxt}\'"\n        if e[\'err\']: x += \' | ERROR text: \' + \'; \'.join(list(e[\'err\'])[:2])\n        if 0 < e[\'loop\'] < e[\'n\']: x += f" | nondeterministic: {e[\'loop\']} of {e[\'n\']} no change"\n        return x\n    def unit_text(s, u):\n        x = f"[page \'{u[\'tm\'][1]}\' {u[\'tm\'][0][:60]}; in {len(u[\'traj\'])} trajs/{u[\'n\']} states] {u[\'bc\']}\\n{u[\'text\']}"\n        if u[\'vals\']:\n            x += \'\\nvalues seen: \' + \' | \'.join(v for v, _ in sorted(u[\'vals\'].items(), key=lambda kv: (-kv[1], kv[0]))[:6])\n        return x\n    def tmpl_text(s, k, maxc=4500):\n        v = s.m.tmpl[k]; inv = v[\'inv\']; tot = sum(inv.values()); n1 = sum(1 for c in inv.values() if c == 1)\n        head = f"PAGE \'{k[1]}\' [{k[0][:80]}] observed in {v[\'n\']} states / {len(v[\'traj\'])} trajectories; {len(inv)} distinct lines, {n1} seen once (unseen-mass estimate {n1 / max(1, tot):.3f}). Element inventory (line: states containing it):"\n        items = [f"{l} x{c}" for l, c in sorted(inv.items(), key=lambda kv: (-kv[1], kv[0])) if len(l) <= 90]\n        out = head; \n        for it in items:\n            if len(out) + len(it) + 3 > maxc: break\n            out += \' | \' + it\n        return out\n    def pack(s, q, budget_tokens, frac=(0.5, 0.25, 0.25, 0.0), cpt=3.5, parts=\'UEP\', ret_units=False):\n        qt = toks(clean_q(q)); B = int(budget_tokens * cpt); out = []; used = []\n        spec = [(\'U\', s.u_bm, lambda i: s.unit_text(s.ud[i])), (\'E\', s.e_bm, lambda i: s.ed[i]), (\'P\', s.p_bm, lambda i: s.m.eps[s.pk[i]])]\n        spec.append((\'T\', s.t_bm, lambda i: s.tmpl_text(s.tk[i])))\n        fr = {k: f for k, f in zip(\'UEPT\', tuple(frac) + (0.0,) * 4)}\n        tot = sum(fr[k] for k in parts); \n        for k, bm, rend in spec:\n            if k not in parts: continue\n            cap = int(B * fr[k] / tot); sz = 0; items = []\n            for i, sc in bm.search(qt, 200):\n                t = rend(i)\n                if sz + len(t) > cap:\n                    t = t[:max(0, cap - sz)] if sz < cap * 0.9 else \'\'\n                    if not t: continue\n                items.append(t); sz += len(t) + 1\n                if sz >= cap: break\n            out.append(f"## {k}\\n" + \'\\n\'.join(items))\n        return \'\\n\'.join(out)\n')
_EMBEDDED['formstate'] = ('99f9bd794dd0df13f94a946b1d10603b774320a874cfa4348bc9f057a2a771c3', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""formstate: generic structured form state from a BrowserGym-style accessibility tree (no site-specific strings).\nControls: textbox, searchbox, combobox, listbox, checkbox, radio, switch, spinbutton, button, tab; properties value, selected, checked,\nrequired, disabled, expanded; options of a combobox/listbox (indented option children; selected ones marked *)."""\nimport re\nCTRL = {"textbox", "searchbox", "combobox", "listbox", "checkbox", "radio", "switch", "spinbutton", "button", "tab", "menuitemcheckbox", "menuitemradio"}\nLINE = re.compile(r"^(\\s*)\\[(\\w+)\\]\\s+(\\w+)\\s*(?:\'((?:[^\'\\\\]|\\\\.)*)\')?(.*)$")\nPROP = re.compile(r"(\\w+)=(\'(?:[^\'\\\\]|\\\\.)*\'|[^,]+)")\ndef parse(text):\n    out = []\n    for ln in (text or "").split("\\n"):\n        m = LINE.match(ln)\n        if not m: continue\n        ind, bid, role, name, rest = m.groups()\n        props = {k: v.strip("\'") for k, v in PROP.findall(rest or "")}\n        flags = {f.strip() for f in (rest or "").split(",") if f.strip() and "=" not in f}\n        out.append((len(ind), bid, role, (name or "").strip(), props, flags))\n    return out\ndef table(text, max_opts=25, max_rows=120):\n    nodes = parse(text); rows = []; i = 0\n    while i < len(nodes) and len(rows) < max_rows:\n        d, bid, role, name, p, fl = nodes[i]\n        if role in CTRL:\n            st = []\n            if "value" in p and p["value"] not in ("", "None"): st.append(f"value={p[\'value\']!r}")\n            for k in ("checked", "selected", "expanded", "pressed"):\n                if k in p: st.append(f"{k}={p[k]}")\n            for k in ("required", "disabled", "readonly"):\n                if k in p or k in fl: st.append(k if p.get(k, "True") not in ("False", "false") else f"not {k}")\n            opts = []\n            if role in ("combobox", "listbox"):\n                j = i + 1\n                while j < len(nodes) and nodes[j][0] > d:\n                    if nodes[j][2] == "option": opts.append(("*" if nodes[j][4].get("selected") in ("True", "true") else "") + nodes[j][3])\n                    j += 1\n            if role == "button" and not st and not opts: i += 1; rows.append(f"button {name!r}") if name else None; continue\n            r = f"{role} {name!r}" + (" " + ", ".join(st) if st else "")\n            if opts: r += " options: " + " | ".join(opts[:max_opts]) + (f" | (+{len(opts)-max_opts} more)" if len(opts) > max_opts else "")\n            rows.append(r)\n        i += 1\n    return rows\n')
_EMBEDDED['formtable'] = ('34cf20d39a79226473b8fdc00e3c76150f2cdbafb3bb074aec43873c84427386', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Form-control table blocks for the G1 renderer.\n\nreference: formstate.table over the page text, rows already shown earlier in the same query omitted.\nengine:    the WARM engine (writerslogic_warm.Warm with experience_form_state) builds the same blocks from\n           trajectory states ingested once at Memory.insert time."""\nimport re, tempfile\nimport formstate\nfrom prompts import form_block\n\nMAX_STR = 16384\nMAX_AXTREE = 4 << 20\nMAX_NODES = 200000\nMAX_DEPTH = 128\n# Same handle, role and quoted-name grammar as formstate.LINE, with the handle optional so every line becomes a node.\nLINE = re.compile(r"^(\\s*)(?:\\[(\\w+)\\]\\s+)?(\\w+)\\s*(?:\'((?:[^\'\\\\]|\\\\.)*)\')?(.*)$")\n\n\ndef clip(s, n=MAX_STR):\n    b = s.encode()\n    return s if len(b) <= n else b[:n].decode("utf-8", "ignore")\n\n\ndef build_tree(text):\n    """Accessibility-tree text to {"role", "name", "props"?, "handle"?, "children"?}; a line nests under the nearest\n    earlier line with less leading whitespace. Several top-level lines get a synthetic RootWebArea parent."""\n    tops = []; stack = []; count = 0\n    for ln in (text or "").split("\\n"):\n        m = LINE.match(ln)\n        if not m: continue\n        if count >= MAX_NODES - 1: break\n        ind, bid, role, name, rest = m.groups()\n        node = {"role": clip(role), "name": clip((name or "").strip())}\n        if rest: node["props"] = clip(rest)\n        if bid: node["handle"] = clip(bid)\n        d = len(ind)\n        while stack and stack[-1][0] >= d: stack.pop()\n        while len(stack) > MAX_DEPTH - 2: stack.pop()\n        (stack[-1][1].setdefault("children", []) if stack else tops).append(node)\n        stack.append((d, node)); count += 1\n    if len(tops) == 1: return tops[0]\n    root = {"role": "RootWebArea", "name": ""}\n    if tops: root["children"] = tops\n    return root\n\n\ndef reference_blocks(texts):\n    shown_rows = set(); out = []\n    for raw in texts:\n        rows = formstate.table(raw); new = [r for r in rows if r not in shown_rows]; shown_rows.update(rows)\n        out.append(form_block(new, len(rows)) if rows else "")\n    return out\n\n\ndef state_event(t, k, st):\n    ev = {"episode": t["id"], "step": int(st["state_index"]), "tree": build_tree(st["accessibility_tree"] or ""), "url": clip(str(st["url"] or ""))}\n    act = st.get("action")\n    if k > 0 and isinstance(act, str) and act.strip(): ev["action"] = {"call": clip(act)}\n    ev["accessibilityTree"] = clip(st["accessibility_tree"] or "", MAX_AXTREE)\n    return ev\n\n\nclass EngineForms:\n    def __init__(self, store_root=None):\n        import writerslogic_warm\n        self.w = writerslogic_warm.Warm(path=tempfile.mkdtemp(prefix="g1-forms-", dir=store_root), experience_form_state=True)\n        self.ingested = set()\n\n    def ingest(self, t):\n        if t["id"] in self.ingested: return\n        for k, st in enumerate(t["states"]): self.w.remember(state_event(t, k, st))\n        self.ingested.add(t["id"])\n\n    def blocks(self, keys):\n        out = list(self.w.experience_form_tables(keys))\n        if len(out) != len(keys): raise RuntimeError(f"engine returned {len(out)} form blocks for {len(keys)} states")\n        return out\n')
_EMBEDDED['ctl_g'] = ('d14f6bd780aab8ff27d282ed5295e47c3278ae80fc3ef89e332d86084b3dc69a', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Gemini (Vertex AI, global endpoint, REST) controller loop and single-call client used by every Gemini stage.\n\nEnvironment:\n  LME2_VERTEX_PROJECT  Google Cloud project that serves the Gemini models\n  LME2_VERTEX_TOKEN    OAuth access token; when unset, `gcloud auth print-access-token` is called every 25 minutes\n"""\nimport json, os, time, subprocess, threading, random, urllib.request, urllib.error\nfrom prompts import PRICES  # noqa: F401\n_tok = [None, 0]; _l = threading.Lock()\ndef token():\n    with _l:\n        if os.environ.get("LME2_VERTEX_TOKEN"):\n            return os.environ["LME2_VERTEX_TOKEN"]\n        if time.time() - _tok[1] > 1500:\n            _tok[0] = subprocess.check_output(["gcloud", "auth", "print-access-token"], text=True, stderr=subprocess.DEVNULL).strip(); _tok[1] = time.time()\n        return _tok[0]\ndef gen(model, body, retries=6):\n    project = os.environ.get("LME2_VERTEX_PROJECT")\n    if not project:\n        raise RuntimeError("set LME2_VERTEX_PROJECT")\n    url = f"https://aiplatform.googleapis.com/v1/projects/{project}/locations/global/publishers/google/models/{model}:generateContent"\n    for k in range(retries):\n        req = urllib.request.Request(url, json.dumps(body).encode(), {"Authorization": "Bearer " + token(), "Content-Type": "application/json"})\n        try:\n            with urllib.request.urlopen(req, timeout=300) as r: return json.load(r)\n        except urllib.error.HTTPError as e:\n            msg = e.read().decode()[:400]\n            if e.code in (429, 500, 503, 504) and k < retries - 1: time.sleep(min(60, 2 ** k + random.random())); continue\n            if e.code == 401: _tok[1] = 0;\n            if e.code == 401 and k < retries - 1: continue\n            raise RuntimeError(f"HTTP {e.code} {msg}")\n        except (urllib.error.URLError, TimeoutError) as e:\n            if k < retries - 1: time.sleep(2 ** k); continue\n            raise\ndef run(model, tools, question, *, max_steps=12, variant="v3", extra=None, max_out=16000, trunc=None, system=None, tool_decls=None, dispatch=None, final_name=\'submit_brief\', final_check=None):\n    """extra: {"thinkingLevel": "HIGH"} or {"thinkingBudget": n}. G1 always passes system, tool_decls and dispatch."""\n    decls = tool_decls; dispatch = dispatch or tools.dispatch\n    contents = [{"role": "user", "parts": [{"text": question}]}]\n    st = dict(steps=0, tool_calls=0, ptok=0, ctok=0, cached=0, forced=False, err=None, trace=[]); t0 = time.perf_counter(); brief = None; empty = 0\n    think = dict(extra or {"thinkingLevel": "MEDIUM"}); think["includeThoughts"] = False\n    for _ in range(max_steps * 2 + 6):\n        force = st["steps"] >= max_steps or empty >= 2\n        body = {"systemInstruction": {"parts": [{"text": system}]}, "contents": contents, "tools": [{"functionDeclarations": decls}],\n                "generationConfig": {"maxOutputTokens": max_out, "thinkingConfig": think}}\n        if force: body["toolConfig"] = {"functionCallingConfig": {"mode": "ANY", "allowedFunctionNames": [final_name]}}; st["forced"] = True\n        try: r = gen(model, body)\n        except Exception as e:\n            st["err"] = repr(e)[:300]; break\n        u = r.get("usageMetadata", {}); st["ptok"] += u.get("promptTokenCount", 0); st["ctok"] += u.get("candidatesTokenCount", 0) + u.get("thoughtsTokenCount", 0); st["steps"] += 1\n        cand = (r.get("candidates") or [{}])[0]; parts = (cand.get("content") or {}).get("parts") or []\n        if not parts:\n            empty += 1\n            if force: break\n            contents.append({"role": "user", "parts": [{"text": f"Continue with a tool call or call {final_name}."}]}); continue\n        contents.append({"role": "model", "parts": parts})\n        calls = [p["functionCall"] for p in parts if "functionCall" in p]\n        if not calls:\n            empty += 1\n            if force: break\n            contents.append({"role": "user", "parts": [{"text": f"Call {final_name} now." if st["steps"] >= max_steps else f"Continue with a tool call or call {final_name}."}]}); continue\n        empty = 0; resp = []\n        for c in calls:\n            a = c.get("args") or {}\n            if c["name"] == final_name:\n                err = final_check(a) if final_check else None\n                if err and st["steps"] <= max_steps: resp.append({"functionResponse": {"name": c["name"], "response": {"result": "REJECTED: " + err}}})\n                else: brief = a; resp.append({"functionResponse": {"name": c["name"], "response": {"result": "ok"}}})\n            else:\n                st["tool_calls"] += 1; st["trace"].append((c["name"], json.dumps(a)[:200]))\n                out = dispatch(c["name"], a) if st["steps"] <= max_steps else f"Tool budget exhausted: call {final_name}."\n                if trunc: out = out[:trunc]\n                resp.append({"functionResponse": {"name": c["name"], "response": {"result": out}}})\n        left = max_steps - st["steps"]\n        note = (f"[Progress: round {st[\'steps\']} of {max_steps} used, {left} remaining." + (f" {final_name} next with the best evidence so far.]" if left <= 2 else "]"))\n        last = resp[-1]["functionResponse"]["response"]; last["result"] = str(last["result"]) + "\\n" + note\n        contents.append({"role": "user", "parts": resp})\n        if brief is not None: break\n    st["seconds"] = time.perf_counter() - t0\n    pin, pout = PRICES.get(model, (0, 0)); st["cost_usd"] = st["ptok"] * pin + st["ctok"] * pout\n    return brief, st\n\n\ndef call_once(model, body):\n    """One forced function call, retried once when no call comes back (the VERIFY/CRUX/OPTCHECK/ANSWER-CHECK loop)."""\n    res = None; err = None; cost = 0.0; u = {}\n    pin, pout = PRICES[model]\n    try:\n        for _ in range(2):\n            rr = gen(model, body); u = rr.get("usageMetadata", {})\n            cost += u.get("promptTokenCount", 0) * pin + (u.get("candidatesTokenCount", 0) + u.get("thoughtsTokenCount", 0)) * pout\n            parts = ((rr.get("candidates") or [{}])[0].get("content") or {}).get("parts") or []\n            c = [p["functionCall"]["args"] for p in parts if "functionCall" in p]\n            if c: res = c[0]; break\n    except Exception as e: err = repr(e)[:300]\n    return res, err, cost, u\n')
_EMBEDDED['tools2'] = ('3ed920fa87bf301da52d97f921bfff56bce5355a515c69ba0ada7d5ec539c2c0', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Tool layer over the compiled memory (envmodel.py) for the memory-side controller. Deterministic, no LLM, no gold.\nCompiled products: region units (R), transition effects (T), episodes (E), page inventories (P), per-step value log (V), trajectory notes (N)."""\nimport re, collections\nimport envmodel as EM\nfrom envmodel import Model, Index, parse_tree, finish, value_lines, toks\n\nclass Model2(Model):\n    """Model plus a per-step value log: vlog[tid] = [(state_index, {element label: value string})]."""\n    def __init__(s):\n        super().__init__(); s.vlog = {}; s.goals = {}\n    def add_traj(s, t):\n        super().add_traj(t)\n        s.goals[t[\'id\']] = t[\'goal\']; log = []\n        for st in t[\'states\']:\n            root, _ = parse_tree(st[\'accessibility_tree\'] or \'\')\n            if root is None: continue\n            finish(root); d = {}\n            for ln in value_lines(root):\n                m = re.match(r"(.*?) ((?:value=|checked|disabled|selected|expanded|pressed|required|level).*)$", ln)\n                if m: d[m.group(1)] = m.group(2)\n            if d: log.append((st[\'state_index\'], d))\n        s.vlog[t[\'id\']] = log\n\nclass Tools:\n    def __init__(s, traj_ids, T, notes=None, k_max=8):\n        s.m = Model2()\n        for i in traj_ids: s.m.add_traj(T[i])\n        s.ix = Index(s.m); s.notes = notes or {}\n        s.nk = [k for k in s.notes if k in s.m.eps]\n        s.nd = [s._note_text(k) for k in s.nk]\n        s.n_bm = EM.BM25([toks(x) for x in s.nd]) if s.nd else None\n        s.ptm = {i: k for i, k in enumerate(s.ix.tk)}\n        s.vl = [(tid, si, el, v) for tid, lg in s.m.vlog.items() for si, d in lg for el, v in d.items()]\n        s.v_bm = EM.BM25([toks(el + \' \' + v) for _, _, el, v in s.vl])\n        s.k_max = k_max\n    def _note_text(s, tid):\n        n = s.notes[tid]; out = []\n        for kind in (\'procedure\', \'hint\'):\n            x = n.get(kind) or {}\n            out.append(f"{kind.upper()} {x.get(\'title\',\'\')}: {x.get(\'description\',\'\')}\\n{x.get(\'content\',\'\')}")\n        return f"Trajectory {tid} goal: {s.m.goals.get(tid,\'\')[:200]}\\n" + \'\\n\'.join(out)\n    # ---- tool implementations; each returns text ----\n    def search(s, kind, query, k=6):\n        k = max(1, min(int(k or 6), s.k_max)); qt = toks(query); out = []\n        if kind == \'regions\':\n            for i, _ in s.ix.u_bm.search(qt, k): out.append(f"R{i} | {s.ix.unit_text(s.ix.ud[i])[:380]}")\n        elif kind == \'transitions\':\n            for i, _ in s.ix.e_bm.search(qt, k): out.append(f"T{i} | {s.ix.ed[i][:380]}")\n        elif kind == \'episodes\':\n            for i, _ in s.ix.p_bm.search(qt, k): out.append(f"E:{s.ix.pk[i]} | {s.m.eps[s.ix.pk[i]][:380]}")\n        elif kind == \'pages\':\n            for i, _ in s.ix.t_bm.search(qt, k):\n                v = s.m.tmpl[s.ix.tk[i]]; out.append(f"P{i} | page \'{s.ix.tk[i][1]}\' [{s.ix.tk[i][0][:70]}] {v[\'n\']} states, {len(v[\'inv\'])} distinct elements")\n        elif kind == \'notes\':\n            if s.n_bm:\n                for i, _ in s.n_bm.search(qt, k): out.append(f"N:{s.nk[i]} | {s.nd[i][:380]}")\n        else: return "unknown kind; use regions, transitions, episodes, pages, notes"\n        return \'\\n\'.join(out) or "no results"\n    def open(s, id_):\n        try:\n            if id_.startswith(\'R\'): return s.ix.unit_text(s.ix.ud[int(id_[1:])])[:4000]\n            if id_.startswith(\'T\'): return s.ix.ed[int(id_[1:])][:2000]\n            if id_.startswith(\'E:\'): return s.m.eps[id_[2:]][:5000]\n            if id_.startswith(\'P\'): return s.ix.tmpl_text(s.ix.tk[int(id_[1:])], maxc=6000)\n            if id_.startswith(\'N:\'): return s.nd[s.nk.index(id_[2:])][:4000]\n        except Exception: pass\n        return "unknown id"\n    def transitions_from(s, page_id, k=12):\n        try: tk = s.ix.tk[int(page_id[1:])]\n        except Exception: return "unknown page id (use an id like P12 from a pages search)"\n        rows = [(e[\'n\'], i) for i, key in enumerate(s.ix.ek) if key[0] == tk for e in [s.m.eff[key]]]\n        rows.sort(reverse=True)\n        return \'\\n\'.join(f"T{i} | {s.ix.ed[i][:420]}" for _, i in rows[:min(int(k or 12), 15)]) or "no recorded actions from this page"\n    def value_history(s, query, k=5):\n        qt = set(toks(query)); hits = [i for i, _ in s.v_bm.search(list(qt), 400)]\n        seq = collections.defaultdict(list)\n        for i in hits:\n            tid, si, el, v = s.vl[i]\n            seq[(tid, el)].append((int(si), v))\n        out = []\n        for (tid, el), xs in sorted(seq.items(), key=lambda kv: -len(kv[1]))[:min(int(k or 5), 8)]:\n            xs.sort(); ch = []; last = None\n            for si, v in xs:\n                if v != last: ch.append(f"step {si}: {v[:80]}"); last = v\n            out.append(f"{tid} {el[:70]}: " + \' -> \'.join(ch[:8]))\n        return \'\\n\'.join(out) or "no values logged for that"\n    def dispatch(s, name, a):\n        try:\n            if name == \'search\': r = s.search(a.get(\'kind\', \'regions\'), a.get(\'query\', \'\'), a.get(\'k\', 6))\n            elif name == \'open\': r = s.open(str(a.get(\'id\', \'\')))\n            elif name == \'transitions_from\': r = s.transitions_from(str(a.get(\'page_id\', \'\')))\n            elif name == \'value_history\': r = s.value_history(a.get(\'query\', \'\'))\n            else: r = \'unknown tool\'\n        except Exception as e: r = f"tool error: {e!r}"[:200]\n        return r[:6500]\n\n')
_EMBEDDED['tools3'] = ('5e944fe365aae8610670d2c3e244e31d4142900e892ecf213c92d16b0b2f8ef4', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Tool layer for the SPAN arm: arch2 compiled-memory tools (index/manifest) + raw-state locators + submit_spans.\nfind_states: BM25 over per-state text (url+action+thought-free AXTree); show_state: preview of one state; submit_spans ends the loop."""\nimport tools2 as T2\nimport envmodel as EM\nfrom envmodel import toks\nfrom prompts import MAX_SPAN_STATES, EXTRA_SPECS, SUBMIT_SPANS, TOOL_SPECS\n\nclass Tools3(T2.Tools):\n    def __init__(s, traj_ids, T, notes=None):\n        super().__init__(traj_ids, T, notes)\n        s.T = {i: T[i] for i in traj_ids}\n        s.sk = []; docs = []\n        for tid in traj_ids:\n            for st in T[tid][\'states\']:\n                s.sk.append((tid, int(st[\'state_index\'])))\n                docs.append(toks((st[\'url\'] or \'\') + \' \' + str(st[\'action\'] or \'\') + \' \' + (st[\'accessibility_tree\'] or \'\')[:20000]))\n        s.s_bm = EM.BM25(docs)\n    def find_states(s, query, k=8):\n        k = max(1, min(int(k or 8), 12)); out = []\n        for i, sc in s.s_bm.search(toks(query), k):\n            tid, si = s.sk[i]; st = s.T[tid][\'states\'][si]\n            out.append(f"{tid} state {si} (of {len(s.T[tid][\'states\'])}) url={str(st[\'url\'])[:80]} action={str(st[\'action\'])[:80]} score={sc:.1f}")\n        return \'\\n\'.join(out) or \'no results\'\n    def show_state(s, trajectory_id, state_index, maxc=2500):\n        try: st = s.T[trajectory_id][\'states\'][int(state_index)]\n        except Exception: return "unknown trajectory_id or state_index (ids as in find_states / episode listings)"\n        return f"{trajectory_id} state {st[\'state_index\']} url={st[\'url\']} action={st[\'action\']}\\n" + (st[\'accessibility_tree\'] or \'\')[:int(maxc)]\n    def goal(s, trajectory_id):\n        t = s.T.get(trajectory_id); return f"{trajectory_id} [{t[\'outcome\']}] {len(t[\'states\'])} states; goal: {t[\'goal\'][:300]}" if t else \'unknown trajectory\'\n    def dispatch(s, name, a):\n        try:\n            if name == \'find_states\': return s.find_states(a.get(\'query\', \'\'), a.get(\'k\', 8))[:6500]\n            if name == \'show_state\': return s.show_state(a.get(\'trajectory_id\', \'\'), a.get(\'state_index\', 0), a.get(\'max_chars\', 2500))[:6500]\n            if name == \'trajectory_goal\': return s.goal(a.get(\'trajectory_id\', \'\'))\n        except Exception as e: return f"tool error: {e!r}"[:200]\n        return super().dispatch(name, a)\n    def check_spans(s, spans):\n        """returns (valid spans, total states, error text or None). Trims nothing: over budget is an error the model must fix."""\n        v = []; tot = 0\n        for sp in spans or []:\n            try:\n                tid = str(sp[\'trajectory_id\']); a = int(sp[\'start_state_index\']); b = int(sp[\'end_state_index\'])\n                n = len(s.T[tid][\'states\'])\n                if not (0 <= a <= b < n): return None, 0, f"span {tid} {a}-{b} outside 0..{n-1}"\n            except Exception as e: return None, 0, f"bad span {sp}: {e!r}"\n            v.append({\'trajectory_id\': tid, \'start_state_index\': a, \'end_state_index\': b}); tot += b - a + 1\n        if tot > MAX_SPAN_STATES: return None, tot, f"spans cover {tot} states, limit is {MAX_SPAN_STATES}; shrink or drop spans (least important last)"\n        return v, tot, None\n\nBASE = [t for t in TOOL_SPECS if t["function"]["name"] != "submit_brief"]\nSPAN_SPECS = BASE + EXTRA_SPECS + [SUBMIT_SPANS]\n')
_EMBEDDED['common'] = ('95a896545c41b6984d802f8145db276b837c9fbeb805529ed20c47427e03543b', '# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Shared inputs for the G1 stages: dataset paths from the environment, the small-tier trajectories, and the\nstate rendering and quote grounding used by VERIFY, CRUX, OPTCHECK and ANSWER-CHECK.\n\nEnvironment:\n  LME2_DATA        LongMemEval-V2 data dir (questions.jsonl, haystacks/, trajectories.jsonl, screenshots/)\n  LME2_UPSTREAM    checkout of the upstream LongMemEval-V2 repository (evaluation/, memory_modules/)\n  LME2_TRAJ_CACHE  pickle cache of the small-tier trajectories (default $LME2_DATA/lme2_small_trajectories.pkl)\n  LME2_NOTES       per-trajectory procedure/hint notes (notes_stage.py output), used by the controller tools\n"""\nimport json, os, pickle, re, sys\nimport fileio  # noqa: E402\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\n\n\ndef _env_path(name):\n    v = os.environ.get(name)\n    if not v:\n        raise SystemExit(f"set {name}")\n    return Path(v).expanduser().resolve()\n\n\ndef data_dir():\n    return _env_path("LME2_DATA")\n\n\ndef upstream_dir():\n    return _env_path("LME2_UPSTREAM")\n\n\ndef add_upstream_path():\n    p = str(upstream_dir())\n    if p not in sys.path:\n        sys.path.insert(0, p)\n\n\ndef questions():\n    return {json.loads(l)["id"]: json.loads(l) for l in fileio.lines(data_dir() / "questions.jsonl")}\n\n\ndef haystack():\n    return fileio.read_json(data_dir() / "haystacks/lme_v2_small.json")\n\n\ndef notes():\n    return fileio.read_json(_env_path("LME2_NOTES"))\n\n\n_ID = re.compile(r\'^\\{"id":\\s*"([^"]+)"\')\n\n\ndef trajectories():\n    """Small-tier trajectories {id: trajectory}, records unchanged from trajectories.jsonl."""\n    cache = Path(os.environ.get("LME2_TRAJ_CACHE") or data_dir() / "lme2_small_trajectories.pkl")\n    if cache.exists():\n        return fileio.read_pickle(cache)\n    want = {t for ids in haystack().values() for t in ids}\n    out = {}\n    with open(data_dir() / "trajectories.jsonl") as f:\n        for line in f:\n            m = _ID.match(line)\n            if m and m.group(1) not in want:\n                continue\n            t = json.loads(line)\n            if t["id"] in want:\n                out[t["id"]] = t\n    missing = want - set(out)\n    if missing:\n        raise SystemExit(f"{len(missing)} haystack trajectories missing from trajectories.jsonl")\n    tmp = cache.with_suffix(".tmp")\n    with open(tmp, "wb") as f:\n        pickle.dump(out, f, protocol=4)\n    tmp.replace(cache)\n    return out\n\n\ndef load_jsonl_by_id(paths):\n    out = {}\n    for f in paths:\n        for l in fileio.lines(f):\n            r = json.loads(l); out[r["id"]] = r\n    return out\n\n\ndef done_ids(out):\n    return {json.loads(l)["id"] for l in fileio.lines(out)} if out.exists() else set()\n\n\n# Rendering and grounding below are the reference stage functions unchanged; they read the module global T.\nT = None\nnorm = lambda s: re.sub(r"\\s+", " ", str(s or "")).strip().lower()\nfrom prompts import PER, TOT  # noqa: E402\n\n\ndef init():\n    global T\n    if T is None:\n        T = trajectories()\n    return T\n\n\ndef state_text(st): return f"{st[\'url\']} {st[\'action\']} {st[\'accessibility_tree\'] or \'\'}"\ndef render(r):\n    parts = []; left = TOT\n    for sp in r["spans"] or []:\n        t = T[sp["trajectory_id"]]\n        parts.append(f"=== trajectory {t[\'id\']} [{t[\'outcome\']}] goal: {str(t[\'goal\'])[:300]}")\n        for st in t["states"][sp["start_state_index"]: sp["end_state_index"] + 1]:\n            tx = (st["accessibility_tree"] or "")[:min(PER, max(left, 0))]; left -= len(tx)\n            parts.append(f"--- state {st[\'state_index\']} url={st[\'url\']} action={str(st[\'action\'])[:200]}\\n{tx}")\n    return "\\n".join(parts)\ndef ground(r, quotes):\n    sel = {}\n    for sp in r["spans"] or []:\n        for st in T[sp["trajectory_id"]]["states"][sp["start_state_index"]: sp["end_state_index"] + 1]: sel[(sp["trajectory_id"], int(st["state_index"]))] = norm(state_text(st))\n    ok = []\n    for qt in quotes or []:\n        k = (str(qt.get("trajectory_id")), int(qt.get("state_index", -1))); tx = re.sub(r"^(action|url)\\s*[=:]\\s*", "", norm(qt.get("text")))\n        if len(tx) >= 2 and k in sel and tx in sel[k]: ok.append({"trajectory_id": k[0], "state_index": k[1], "text": re.sub(r"\\s+", " ", qt["text"]).strip()})\n    return ok\n')
_EMBEDDED['rules'] = ('39f95162833b072aedb8708decec809a42641d3d363357d8c61574dc8f628bd1', '#!/usr/bin/env python3\n# Copyright 2024-2026 WritersLogic Contributors\n# SPDX-License-Identifier: Apache-2.0\n"""Deterministic G1 stages (no model calls, no labels).\n  final-rule     <ctl.jsonl...> --verify v.jsonl --crux x.jsonl --out spans_f1.json\n                 c1 verdict: absent when the controller says absent or VERIFY premise is violated (VERIFY analysis)\n                 or CRUX verdict is missing (CRUX note); otherwise controller analysis and support\n  choice-ids     ids.json out.json: questions offering explicit choices (regex on the question text)\n  undecided-ids  opt.jsonl out.json: option-checked questions with no option supported by a grounded quote\n  answers        reader_cache.json out.jsonl: pass-1 reader answers for ANSWER-CHECK (boxed answer, else the last 1500 chars)\n  mkp6           --base spans_f1.json [--pass2 pass2.jsonl --out-spans spans_s2.json] [--anscheck anscheck.jsonl --out-first reread_first.json]\n                 pass-2 spans applied over f1 (support kept from f1; analysis kept when f1 said absent); Evidence Check text\n                 for answers ANSWER-CHECK finds contradicted with >=1 grounded quote when the f1 verdict is not absent"""\nimport argparse, hashlib, json\nimport fileio  # noqa: E402\nfrom prompts import CHOICE_PATTERN, evidence_check\n\n\ndef qkey(q): return hashlib.sha256(q.encode()).hexdigest()[:20]\n\n\ndef final_rule(C, V, X, Q):\n    out = {}\n    for i, c in C.items():\n        v = V.get(i) or {}; x = X.get(i) or {}\n        if c[\'support\'] == \'absent\' or v.get(\'premise\') == \'violated\': an, sup = v.get(\'analysis\') or c[\'analysis\'], \'absent\'\n        elif x.get(\'verdict\') == \'missing\': an, sup = x.get(\'note\', \'\'), \'absent\'\n        else: an, sup = c[\'analysis\'], c[\'support\']\n        out[qkey(Q[i])] = {\'id\': i, \'analysis\': an, \'spans\': c[\'spans\'] or [], \'support\': sup, \'seconds\': c[\'stats\'][\'seconds\']}\n    return out\n\n\ndef choice_ids(ids, Q): return [i for i in ids if CHOICE_PATTERN.search(Q[i][\'question\'])]\n\n\ndef undecided_ids(O): return [o[\'id\'] for o in O if not any(g[\'verdict\'] == \'supported\' and g[\'quotes\'] for g in o[\'grounded\'])]\n\n\ndef merge_pass2(spans, first_pass):\n    """Pass-2 spans first, then first-pass spans not already present (exact dict equality) while the total stays <= 20 states."""\n    merged = list(spans or []); n = sum(s["end_state_index"] - s["start_state_index"] + 1 for s in merged)\n    for s in first_pass or []:\n        k = s["end_state_index"] - s["start_state_index"] + 1\n        if s not in merged and n + k <= 20: merged.append(s); n += k\n    return merged\n\n\ndef pass1_answers(cache):\n    out = []\n    for k, v in cache.items():\n        b = (v[\'output\'][\'response_parsed_boxed\'] or \'\').strip()\n        out.append({\'id\': k.split(\'|\')[0], \'answer\': b if b else (v[\'output\'][\'response_raw\'] or \'\')[-1500:]})\n    return out\n\n\ndef reread_first(A, base, Q):\n    first = {}\n    for a in A:\n        if (a[\'c\'] or {}).get(\'verdict\') == \'contradicted\' and a[\'grounded\'] and base[a[\'id\']][\'support\'] != \'absent\':\n            first[qkey(Q[a[\'id\']])] = evidence_check(a[\'grounded\'])\n    return first\n\n\ndef apply_pass2(base, P2, Q):\n    S = {qkey(Q[i]): dict(v) for i, v in base.items()}\n    for r in P2:\n        if r[\'spans\']: S[qkey(Q[r[\'id\']])].update(spans=r[\'spans\'], analysis=r[\'analysis\'] if S[qkey(Q[r[\'id\']])][\'support\'] != \'absent\' else S[qkey(Q[r[\'id\']])][\'analysis\'])\n    return S\n\n\ndef _jsonl(p): return [json.loads(l) for l in fileio.lines(p)]\n\n\ndef main():\n    import common\n    ap = argparse.ArgumentParser(); sub = ap.add_subparsers(dest="cmd", required=True)\n    f = sub.add_parser("final-rule"); f.add_argument("ctl", nargs="+"); f.add_argument("--verify", required=True); f.add_argument("--crux", required=True); f.add_argument("--out", required=True)\n    c = sub.add_parser("choice-ids"); c.add_argument("ids"); c.add_argument("out")\n    u = sub.add_parser("undecided-ids"); u.add_argument("opt"); u.add_argument("out")\n    w = sub.add_parser("answers"); w.add_argument("cache"); w.add_argument("out")\n    m = sub.add_parser("mkp6"); m.add_argument("--base", required=True); m.add_argument("--pass2"); m.add_argument("--out-spans"); m.add_argument("--anscheck"); m.add_argument("--out-first")\n    a = ap.parse_args()\n    if a.cmd == "final-rule":\n        Q = {i: q[\'question\'] for i, q in common.questions().items()}\n        C = common.load_jsonl_by_id(a.ctl)\n        V = {r[\'id\']: r[\'v\'] for r in _jsonl(a.verify)}; X = {r[\'id\']: r[\'c\'] for r in _jsonl(a.crux)}\n        out = final_rule(C, V, X, Q); fileio.write_json(out, a.out); print(a.out, len(out), \'absent\', sum(o[\'support\'] == \'absent\' for o in out.values()))\n    elif a.cmd == "choice-ids":\n        out = choice_ids(fileio.read_json(a.ids), common.questions()); fileio.write_json(out, a.out); print(len(out))\n    elif a.cmd == "undecided-ids":\n        out = undecided_ids(_jsonl(a.opt)); fileio.write_json(out, a.out); print(len(out))\n    elif a.cmd == "answers":\n        with open(a.out, \'w\') as f:\n            for r in pass1_answers(fileio.read_json(a.cache)): f.write(json.dumps(r) + \'\\n\')\n    else:\n        Q = {i: q[\'question\'] for i, q in common.questions().items()}\n        base = {v[\'id\']: v for v in fileio.read_json(a.base).values()}\n        if a.anscheck:\n            A = _jsonl(a.anscheck); first = reread_first(A, base, Q)\n            fileio.write_json(first, a.out_first); print(\'reread fires\', len(first), \'of\', len(A))\n        if a.pass2:\n            P2 = _jsonl(a.pass2); fileio.write_json(apply_pass2(base, P2, Q), a.out_spans); print(\'pass2 applied\', len(P2))\n\n\nif __name__ == "__main__":\n    main()\n')
