# Live orchestration. Everything below calls the embedded stage code; no prompt, schema, rule, threshold or model setting
# is defined here.
import asyncio as _asyncio
import hashlib as _hashlib
import http.client as _http
import json as _json
import os as _os
import random
import sys as _sys
import threading as _threading
import time as _time
import types as _types
from concurrent.futures import ThreadPoolExecutor as _TPE
from pathlib import Path as _Path
from types import SimpleNamespace as _NS


def _load_embedded():
    """Loads the embedded adapter modules under their own names (they import each other by name), then restores
    sys.modules so the plain names do not leak; the modules stay reachable as warm_g1_live._<name>."""
    mods = {}
    saved = {n: _sys.modules.get(n) for n in _EMBEDDED}
    try:
        for name, (digest, text) in _EMBEDDED.items():
            if _hashlib.sha256(text.encode()).hexdigest() != digest:
                raise ImportError(f"embedded {name}.py does not match its sha256")
            m = _types.ModuleType(name)
            m.__file__ = f"{__file__}:{name}.py"
            _sys.modules[name] = m
            exec(compile(text, f"<warm_g1_live:{name}.py>", "exec"), m.__dict__)
            mods[name] = m
    finally:
        for n, old in saved.items():
            if old is None:
                _sys.modules.pop(n, None)
            else:
                _sys.modules[n] = old
    for n, m in mods.items():
        _sys.modules[f"warm_g1_live._{n}"] = m
    return mods


_M = _load_embedded()
