_ORIG_GEN = CTL.gen
READER_BACKEND = None  # callable(messages) -> text; None means the live vLLM endpoint
_VERTEX_HOST = "aiplatform.googleapis.com"
_conn = _threading.local()


def _post(path, data, headers):
    """One POST on this thread's persistent HTTPS connection to Vertex. A connection the server closed while idle fails
    before any response arrives; it is reopened and the request sent once more. Returns (status, body bytes)."""
    for attempt in (0, 1):
        c = getattr(_conn, "c", None)
        if c is None:
            c = _conn.c = _http.HTTPSConnection(_VERTEX_HOST, timeout=300)
        try:
            c.request("POST", path, data, headers)
            r = c.getresponse()
            raw = r.read()
        except (_http.RemoteDisconnected, BrokenPipeError, ConnectionResetError, _http.CannotSendRequest) as e:
            c.close(); _conn.c = None
            if attempt:
                raise OSError(f"Vertex connection lost twice: {e!r}") from e
            continue
        except BaseException:
            c.close(); _conn.c = None
            raise
        if r.will_close:
            c.close(); _conn.c = None
        return r.status, raw


def _live_gen(model, body, retries=6):
    """CTL.gen (the embedded client) with its request bytes, URL, headers, retry schedule and errors unchanged, sent over
    persistent connections instead of a new TLS connection per call (the controller makes about 11 sequential calls)."""
    project = _os.environ.get("LME2_VERTEX_PROJECT")
    if not project:
        raise RuntimeError("set LME2_VERTEX_PROJECT")
    path = f"/v1/projects/{project}/locations/global/publishers/google/models/{model}:generateContent"
    data = _json.dumps(body).encode()
    for k in range(retries):
        try:
            status, raw = _post(path, data, {"Authorization": "Bearer " + CTL.token(), "Content-Type": "application/json"})
        except (OSError, _http.HTTPException):
            if k < retries - 1:
                _time.sleep(2 ** k); continue
            raise
        if status == 200:
            return _json.loads(raw)
        msg = raw.decode(errors="replace")[:400]
        if status in (429, 500, 503, 504) and k < retries - 1:
            _time.sleep(min(60, 2 ** k + random.random())); continue
        if status == 401:
            CTL._tok[1] = 0
            if k < retries - 1:
                continue
        raise RuntimeError(f"HTTP {status} {msg}")


GEN_BACKEND = _live_gen  # the replay check substitutes recorded responses


def _gen(model, body, retries=6):
    """Every Gemini call of every stage goes through here: spend cap, per-call usage written to disk."""
    if _ACCT["cap"] is not None and _ACCT["usd"] >= _ACCT["cap"]:
        raise RuntimeError("Gemini spend cap reached")
    label = getattr(_tl, "label", ("?", "?"))
    t0 = _time.perf_counter()
    # Vertex answers 429 (resource exhausted) under shared load; the embedded client gives up after about a minute, so
    # a 429 is retried here for up to 20 minutes. Only availability changes; the request is the same.
    for k in range(40):
        try:
            r = GEN_BACKEND(model, body, retries); break
        except RuntimeError as e:
            if not str(e).startswith("HTTP 429") or k == 39:
                raise
            with _acct_lock:
                _ACCT["r429"] = _ACCT.get("r429", 0) + 1
            _time.sleep(min(60.0, 15.0 + 5 * k) * (0.75 + 0.5 * random.random()))
    u = r.get("usageMetadata", {}) or {}
    pin, pout = P.PRICES.get(model, (0, 0))
    ct = u.get("candidatesTokenCount", 0) + u.get("thoughtsTokenCount", 0)
    cost = u.get("promptTokenCount", 0) * pin + ct * pout
    rec = {"t": round(_time.time(), 3), "q": label[0], "stage": label[1], "model": model, "ptok": u.get("promptTokenCount", 0),
           "ctok": ct, "cached": u.get("cachedContentTokenCount", 0), "usd": cost, "s": round(_time.perf_counter() - t0, 3)}
    with _acct_lock:
        _ACCT["usd"] += cost; _ACCT["calls"] += 1
        _ACCT["by_q"][label[0]] = _ACCT["by_q"].get(label[0], 0.0) + cost
        if _ACCT["path"]:
            with open(_ACCT["path"], "a") as f:
                f.write(_json.dumps(rec) + "\n")
    return r


CTL.gen = _gen


def _labelled(qk, stage, fn, *a):
    _tl.label = (qk, stage)
    t0 = _time.perf_counter()
    try:
        return fn(*a), _time.perf_counter() - t0
    finally:
        _tl.label = ("?", "?")


class _LockedForms:
    def __init__(self, inner):
        self.inner = inner; self.lock = _threading.Lock()

    def ingest(self, t):
        with self.lock:
            self.inner.ingest(t)

    def blocks(self, keys):
        with self.lock:
            return self.inner.blocks(keys)


@register_memory
class G1LiveMemory(Memory):
    """memory_params:
      notes          controller notes json (one procedure and one hint note per trajectory, written at ingest by the reader)
      reread         true: verify-and-reread (reader draft + ANSWER-CHECK); false: operating point without the draft
      skip_draft_when_absent   true: no draft or ANSWER-CHECK when the final-rule verdict is absent (same context, less latency)
      form_backend   engine (WARM experience_form_tables) | reference (formstate.py)
      screens_root   trajectory screenshot dir (<root>/<trajectory id>/<file>)
      store_root     parent dir for the WARM engine store
      reader_base_url, memory_context_max_tokens   reader endpoint and the harness context cap, for the draft
      trace_path, gemini_usage_path, gemini_cap_usd   per-query timings, per-call Gemini usage, hard spend stop"""
    memory_type = "warm_g1_live"
    DEFAULTS = {"notes": None, "reread": True, "skip_draft_when_absent": False, "form_backend": "engine", "screens_root": None, "store_root": None,
                "reader_base_url": "http://localhost:8023/v1", "memory_context_max_tokens": 200000,
                "trace_path": None, "gemini_usage_path": None, "gemini_cap_usd": None}

    def __init__(self, memory_params):
        super().__init__(memory_params)
        self.p = {**self.DEFAULTS, **memory_params}
        if self.p["form_backend"] not in ("engine", "reference"):
            raise ValueError("form_backend must be engine or reference")
        if not self.p["notes"]:
            raise ValueError("notes is required")
        with open(self.p["notes"]) as f:
            self.notes = _json.load(f)
        self.trajs = {}; self.order = []; self.domain = None
        self.forms = _LockedForms(FT.EngineForms(self.p["store_root"])) if self.p["form_backend"] == "engine" else None
        self._tools = None; self._decls = None; self._cv = _threading.Condition()
        self._want = self._have = 0; self._building = False; self._build_err = None
        with _acct_lock:
            if self.p["gemini_cap_usd"] is not None:
                _ACCT["cap"] = float(self.p["gemini_cap_usd"])
            if self.p["gemini_usage_path"]:
                _ACCT["path"] = self.p["gemini_usage_path"]

    def insert(self, trajectory):
        d = trajectory.get("domain")
        if self.domain is not None and d != self.domain:
            raise ValueError("one memory holds one domain's haystack")
        self.domain = d
        if trajectory["id"] not in self.trajs:
            self.order.append(trajectory["id"])
        self.trajs[trajectory["id"]] = trajectory
        if self.forms is not None:
            self.forms.ingest(trajectory)
        with self._cv:
            if COMMON.T is None:
                COMMON.T = {}
            COMMON.T.update(self.trajs)
            self._want += 1
            if not self._building:
                self._building = True
                _threading.Thread(target=self._build_tools, daemon=True).start()
        if self._decls is None:
            self._decls = [{"name": t["function"]["name"], "description": t["function"]["description"],
                            "parameters": P._schema(t["function"]["parameters"])} for t in T3.SPAN_SPECS]

    def _build_tools(self):
        """The controller index is a function of the whole haystack in insertion order. It is rebuilt in the background
        while inserts arrive, so the build is not repeated per insert; a query waits for the build of the final haystack,
        and that wait is part of its measured time."""
        while True:
            with self._cv:
                gen, order = self._want, list(self.order)
            try:
                tools, err = T3.Tools3(order, self.trajs, self.notes), None
            except Exception as e:
                tools, err = None, e
            with self._cv:
                if self._want == gen or err is not None:
                    self._tools, self._have, self._build_err, self._building = tools, gen, err, False
                    self._cv.notify_all()
                    return

    def _ready_tools(self):
        with self._cv:
            self._cv.wait_for(lambda: self._have == self._want or self._build_err is not None)
            if self._build_err is not None:
                raise RuntimeError("controller index build failed") from self._build_err
            return self._tools

    # --- stages (one question) -------------------------------------------------------------------------------------
    def _controller(self, question, base=None):
        """span_stage.one (pass 1) or ctl_pass2.one (base = pass-1 record, question = the pass-2 memory note)."""
        tl = self._ready_tools()
        b, st = CTL.run(P.CONTROLLER_MODEL, tl, question, max_steps=P.CONTROLLER_MAX_STEPS, extra=dict(P.CONTROLLER_EXTRA),
                        system=P.workflow(P.CONTROLLER_MAX_STEPS), tool_decls=self._decls, dispatch=tl.dispatch,
                        final_name="submit_spans", final_check=lambda x: tl.check_spans(x.get("spans"))[2])
        spans, tot, err = tl.check_spans((b or {}).get("spans")) if b else (None, 0, "no brief")
        if base is None:
            return {"id": QID, "analysis": (b or {}).get("analysis"), "support": (b or {}).get("support"), "spans": spans,
                    "span_err": err, "n_states": tot, "stats": st}
        merged = RULES.merge_pass2(spans, base["spans"])
        return {"id": QID, "analysis": (b or {}).get("analysis") or base["analysis"], "support": (b or {}).get("support") or base["support"],
                "spans": merged, "stats": st, "span_err": err}

    @staticmethod
    def _check(stage, q, r, answer=None):
        """check_stages.one for one question: request body, one forced call, grounding."""
        render, ground = COMMON.render, COMMON.ground
        if stage == "verify": body = P.stage_body(P.VERIFY_SYSTEM, P.verify_message(q, r, render(r)), P.VERIFY_DECL, "verify")
        elif stage == "crux": body = P.stage_body(P.CRUX_SYSTEM, P.states_message(q, render(r)), P.CRUX_DECL, "cite")
        elif stage == "optcheck": body = P.stage_body(P.OPTCHECK_SYSTEM, P.states_message(q, render(r)), P.OPTCHECK_DECL, "cite")
        else: body = P.stage_body(P.ANSCHECK_SYSTEM, P.anscheck_message(q, answer, render(r)), P.ANSCHECK_DECL, "cite")
        res, err, cost, u = CTL.call_once(STAGE_MODEL, body)
        if stage == "optcheck":
            return {"id": QID, "c": res, "grounded": [dict(o, quotes=ground(r, o.get("quotes"))) for o in (res or {}).get("options") or []], "err": err}
        if stage == "anscheck":
            return {"id": QID, "c": res, "grounded": ground(r, (res or {}).get("quotes")) if res else [], "err": err}
        return {"id": QID, "v" if stage == "verify" else "c": res, "err": err}

    def _render(self, query, S, first):
        """g1_memory.G1SpanMemory.query over in-memory spans (and the Evidence Check text when the reread fires)."""
        r = object.__new__(G1.G1SpanMemory)
        r.p = {**G1.G1SpanMemory.DEFAULTS, "mode": "span_v", "form_backend": self.p["form_backend"], "screens_root": self.p["screens_root"],
               "store_root": self.p["store_root"], "first": "live" if first else None}
        r.trajs = self.trajs; r._s = S; r._f = first; r._engine = self.forms
        return G1.G1SpanMemory.query(r, query)

    def _draft(self, query, query_image, items):
        """The reader's pass-1 answer on exactly the messages the harness builds from these items (reader_stage settings)."""
        import evaluation.harness as H
        ctx, _, _ = H.truncate_memory_context(H.validate_memory_context_items(items, question_id="g1-draft"),
                                              max_tokens=int(self.p["memory_context_max_tokens"]), question_id="g1-draft")
        messages, _ = H.build_messages(system_prompt=H.get_system_prompt(self.domain), question_text=query, image_path=query_image, memory_context=ctx)
        text, err = "", None
        if READER_BACKEND is not None:
            text = READER_BACKEND(messages)
        else:
            args = _NS(base_url=self.p["reader_base_url"], **READER_ARGS)

            async def call():
                client = H.create_async_client(args.base_url, args.api_key_env, args.api_key_file)
                try:
                    return await H.call_reader_model_async(client, args, messages)
                finally:
                    await client.close()
            for k in range(3):
                try:
                    text = _asyncio.run(call())[0]; err = None; break
                except H.BadRequestError as e:  # reader_stage records an empty answer for a rejected request
                    text, err = "", repr(e)[:200]; break
                except Exception as e:  # transient; reader_stage leaves these for a rerun
                    err = repr(e)[:200]; _time.sleep(5 * (k + 1))
        out = {"response_raw": text, "response_parsed_boxed": H.extract_boxed_answer(text)}
        return RULES.pass1_answers({QID: {"output": out}})[0]["answer"], messages, err

    def query(self, query, query_image=None):
        if _ACCT["cap"] is not None and _ACCT["usd"] >= _ACCT["cap"]:
            raise RuntimeError("Gemini spend cap reached: stopping the run rather than answering with degraded stages")
        t_start = _time.perf_counter()
        qk = _hashlib.sha256(query.encode()).hexdigest()[:20]
        tr = {"qkey": qk, "reread": bool(self.p["reread"])}
        Q = {QID: query}
        C, tr["t_ctl"] = _labelled(qk, "controller", self._controller, query)
        choice = bool(RULES.choice_ids([QID], {QID: {"question": query}}))
        with _TPE(3) as ex:
            fv = ex.submit(_labelled, qk, "verify", self._check, "verify", query, C)
            fx = ex.submit(_labelled, qk, "crux", self._check, "crux", query, C)
            fo = ex.submit(_labelled, qk, "optcheck", self._check, "optcheck", query, C) if choice else None
            (V, tv), (X, tx) = fv.result(), fx.result()
            O, to = fo.result() if fo else (None, 0.0)
        tr.update(t_verify=tv, t_crux=tx, t_opt=to, choice=choice)
        base = {v["id"]: v for v in RULES.final_rule({QID: C}, {QID: V["v"]}, {QID: X["c"]}, Q).values()}
        P2 = []
        tr["undecided"] = bool(O is not None and RULES.undecided_ids([O]))
        if tr["undecided"]:
            opts = "; ".join(o["option"][:80] for o in O["grounded"]) or P.PASS2_NO_OPTIONS
            r2, tr["t_pass2"] = _labelled(qk, "pass2", self._controller, P.pass2_question(query, opts), C)
            P2 = [r2]
        S = RULES.apply_pass2(base, P2, Q)
        items = self._render(query, S, None)
        tr.update(support=base[QID]["support"], n_spans=len(S[qk]["spans"] or []), ctl_err=C["stats"].get("err"), span_err=C["span_err"],
                  stage_err=[s for s, r in (("verify", V), ("crux", X), ("optcheck", O)) if r and r.get("err")])
        tr["t_pass1_context"] = _time.perf_counter() - t_start
        # reread_first never fires on an absent verdict, so the draft and ANSWER-CHECK cannot change the context there.
        if self.p["reread"] and not (self.p["skip_draft_when_absent"] and base[QID]["support"] == "absent"):
            t0 = _time.perf_counter()
            answer, _, derr = self._draft(query, query_image, items)
            tr["t_draft"] = _time.perf_counter() - t0; tr["draft_err"] = derr
            A, tr["t_anscheck"] = _labelled(qk, "anscheck", self._check, "anscheck", query, C, answer)
            first = RULES.reread_first([A], base, Q)
            tr["fired"] = bool(first)
            if first:
                items = self._render(query, S, first)
        tr["t_total"] = _time.perf_counter() - t_start
        with _acct_lock:
            tr["gemini_usd"] = _ACCT["by_q"].get(qk, 0.0); tr["r429_total"] = _ACCT.get("r429", 0)
        if self.p["trace_path"]:
            with _acct_lock, open(self.p["trace_path"], "a") as f:
                f.write(_json.dumps(tr) + "\n")
        return items
